// Initialize economic simulation cycle
const triggerData = $input.first().json;
const simulationType = $node['Economic Simulation Trigger'].isRunning ? 'scheduled' : 'manual';

const simulationConfig = {
  simulation_id: `econ_sim_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  simulation_type: simulationType,
  timestamp: new Date().toISOString(),
  trigger_data: triggerData || {},
  simulation_parameters: {
    market_volatility: triggerData.market_volatility || 'normal', // low, normal, high, extreme
    trade_activity: triggerData.trade_activity || 'normal', // low, normal, high
    external_shocks: triggerData.external_shocks || [],
    player_actions: triggerData.player_actions || [],
    seasonal_factors: triggerData.seasonal_factors || 'auto',
    regional_focus: triggerData.regional_focus || 'all' // all, specific regions
  },
  simulation_scope: {
    markets: ['all'], // commodities, services, magical, labor
    regions: ['all'], // all campaigns regions
    trade_routes: ['active'], // active, all, specific
    price_bands: ['all'], // budget, standard, premium, luxury
    time_horizon: 'current_cycle' // current_cycle, short_term, long_term
  }
};

return [{ json: simulationConfig }];

// Process economic data and prepare for simulation
const simulationConfig = $input.first().json;
const campaigns = $input.last().json.results || [];

const processedCampaigns = campaigns.map(campaign => {
  const { campaignId, worldState, economicData, lastUpdate } = campaign;

  // Extract and validate economic components
  const currentEconomy = {
    markets: economicData?.markets || initializeDefaultMarkets(),
    trade_routes: economicData?.trade_routes || [],
    regional_prices: economicData?.regional_prices || {},
    supply_levels: economicData?.supply_levels || {},
    demand_levels: economicData?.demand_levels || {},
    price_history: economicData?.price_history || [],
    trade_activity: economicData?.trade_activity || {},
    market_conditions: economicData?.market_conditions || 'stable'
  };

  // Calculate time-based factors
  const now = new Date();
  const lastUpdateDate = lastUpdate ? new Date(lastUpdate) : new Date(now.getTime() - 6 * 60 * 60 * 1000);
  const hoursSinceUpdate = (now - lastUpdateDate) / (1000 * 60 * 60);

  const timeFactors = {
    time_multiplier: Math.min(hoursSinceUpdate / 6, 2),
    seasonal_adjustment: calculateSeasonalAdjustment(worldState),
    day_cycle_adjustment: calculateDayCycleAdjustment(now),
    market_fatigue: calculateMarketFatigue(currentEconomy.price_history, hoursSinceUpdate)
  };

  // Analyze current market conditions
  const marketAnalysis = analyzeMarketConditions(currentEconomy, worldState, timeFactors);

  return {
    campaignId,
    currentEconomy,
    timeFactors,
    marketAnalysis,
    lastUpdate,
    simulationPriority: calculateSimulationPriority(marketAnalysis, timeFactors)
  };
});

// Sort by simulation priority
processedCampaigns.sort((a, b) => b.simulationPriority - a.simulationPriority);

function initializeDefaultMarkets() {
  return {
    commodities: {
      food: { base_price: 10, current_price: 10, supply: 100, demand: 100 },
      water: { base_price: 5, current_price: 5, supply: 100, demand: 100 },
      materials: { base_price: 25, current_price: 25, supply: 100, demand: 100 },
      weapons: { base_price: 50, current_price: 50, supply: 100, demand: 100 },
      armor: { base_price: 75, current_price: 75, supply: 100, demand: 100 },
      tools: { base_price: 15, current_price: 15, supply: 100, demand: 100 }
    },
    services: {
      lodging: { base_price: 20, current_price: 20, supply: 100, demand: 100 },
      transportation: { base_price: 30, current_price: 30, supply: 100, demand: 100 },
      crafting: { base_price: 40, current_price: 40, supply: 100, demand: 100 },
      healing: { base_price: 60, current_price: 60, supply: 100, demand: 100 },
      information: { base_price: 25, current_price: 25, supply: 100, demand: 100 }
    },
    magical: {
      potions: { base_price: 100, current_price: 100, supply: 100, demand: 100 },
      scrolls: { base_price: 150, current_price: 150, supply: 100, demand: 100 },
      components: { base_price: 80, current_price: 80, supply: 100, demand: 100 },
      enchantments: { base_price: 500, current_price: 500, supply: 100, demand: 100 },
      artifacts: { base_price: 1000, current_price: 1000, supply: 100, demand: 100 }
    },
    labor: {
      unskilled: { base_price: 5, current_price: 5, supply: 100, demand: 100 },
      skilled: { base_price: 15, current_price: 15, supply: 100, demand: 100 },
    expert: { base_price: 35, current_price: 35, supply: 100, demand: 100 },
      master: { base_price: 75, current_price: 75, supply: 100, demand: 100 },
      specialist: { base_price: 150, current_price: 150, supply: 100, demand: 100 }
    }
  };
}

function calculateSeasonalAdjustment(worldState) {
  const currentSeason = worldState.currentSeason || 'spring';
  const seasonalFactors = {
    spring: { food: 1.2, materials: 1.0, services: 1.1, magical: 0.9 },
    summer: { food: 0.8, materials: 1.2, services: 1.3, magical: 1.0 },
    autumn: { food: 0.9, materials: 1.1, services: 1.0, magical: 1.1 },
    winter: { food: 1.3, materials: 0.9, services: 0.8, magical: 1.2 }
  };

  return seasonalFactors[currentSeason] || seasonalFactors.spring;
}

function calculateDayCycleAdjustment(now) {
  const hour = now.getHours();

  if (hour >= 6 && hour < 10) { // Early morning
    return { services: 1.2, labor: 1.3, food: 1.1 };
  } else if (hour >= 10 && hour < 14) { // Midday
    return { services: 1.0, labor: 1.0, food: 0.9 };
  } else if (hour >= 14 && hour < 18) { // Afternoon
    return { services: 1.1, labor: 0.9, food: 1.0 };
  } else if (hour >= 18 && hour < 22) { // Evening
    return { services: 1.3, labor: 0.7, food: 1.2 };
  } else { // Night
    return { services: 0.6, labor: 0.3, food: 0.8 };
  }
}

function calculateMarketFatigue(priceHistory, hoursSinceUpdate) {
  if (!priceHistory || priceHistory.length < 5) return 1.0;

  const recentPrices = priceHistory.slice(-5);
  const volatility = calculateVolatility(recentPrices);

  // High volatility leads to market fatigue
  if (volatility > 0.3) return 0.8;
  if (volatility > 0.2) return 0.9;
  if (volatility < 0.05) return 1.1;

  return 1.0;
}

function calculateVolatility(prices) {
  if (prices.length < 2) return 0;

  const returns = [];
  for (let i = 1; i < prices.length; i++) {
    returns.push((prices[i] - prices[i-1]) / prices[i-1]);
  }

  const mean = returns.reduce((a, b) => a + b, 0) / returns.length;
  const variance = returns.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / returns.length;

  return Math.sqrt(variance);
}

function analyzeMarketConditions(economy, worldState, timeFactors) {
  const analysis = {
    overall_condition: 'stable',
    market_pressure: {},
    price_trends: {},
    supply_demand_imbalance: {},
    trade_route_efficiency: {},
    external_factors: [],
    volatility_indicators: {},
    opportunity_factors: []
  };

  // Analyze each market category
  Object.entries(economy.markets).forEach(([category, goods]) => {
    const categoryAnalysis = analyzeMarketCategory(category, goods, timeFactors);
    analysis.market_pressure[category] = categoryAnalysis.pressure;
    analysis.price_trends[category] = categoryAnalysis.trend;
    analysis.supply_demand_imbalance[category] = categoryAnalysis.imbalance;
    analysis.volatility_indicators[category] = categoryAnalysis.volatility;
  });

  // Analyze trade routes
  analysis.trade_route_efficiency = analyzeTradeRoutes(economy.trade_routes, worldState);

  // Identify external factors
  analysis.external_factors = identifyExternalFactors(worldState, economy);

  // Identify opportunities
  analysis.opportunity_factors = identifyOpportunities(analysis, worldState);

  // Determine overall condition
  analysis.overall_condition = determineOverallCondition(analysis);

  return analysis;
}

function analyzeMarketCategory(category, goods, timeFactors) {
  const goodsData = Object.values(goods);

  const avgSupply = goodsData.reduce((sum, good) => sum + good.supply, 0) / goodsData.length;
  const avgDemand = goodsData.reduce((sum, good) => sum + good.demand, 0) / goodsData.length;
  const avgPrice = goodsData.reduce((sum, good) => sum + good.current_price, 0) / goodsData.length;
  const avgBasePrice = goodsData.reduce((sum, good) => sum + good.base_price, 0) / goodsData.length;

  const pressure = (avgDemand - avgSupply) / 100; // -1 to 1
  const trend = (avgPrice - avgBasePrice) / avgBasePrice; // percentage change
  const imbalance = Math.abs(pressure);
  const volatility = calculateGoodsVolatility(goodsData);

  // Apply time factors
  const seasonalAdjustment = timeFactors.seasonal_adjustment[category] || 1.0;
  const dayCycleAdjustment = timeFactors.day_cycle_adjustment[category] || 1.0;
  const fatigueAdjustment = timeFactors.market_fatigue;

  return {
    pressure: pressure * seasonalAdjustment * dayCycleAdjustment,
    trend: trend,
    imbalance: imbalance,
    volatility: volatility,
    adjusted_pressure: pressure * seasonalAdjustment * dayCycleAdjustment * fatigueAdjustment,
    seasonal_factor: seasonalAdjustment,
    day_cycle_factor: dayCycleAdjustment,
    fatigue_factor: fatigueAdjustment
  };
}

function calculateGoodsVolatility(goodsData) {
  if (goodsData.length < 2) return 0;

  const priceChanges = goodsData.map(good => 
    (good.current_price - good.base_price) / good.base_price
  );

  const mean = priceChanges.reduce((a, b) => a + b, 0) / priceChanges.length;
  const variance = priceChanges.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / priceChanges.length;

  return Math.sqrt(variance);
}

function analyzeTradeRoutes(tradeRoutes, worldState) {
  const efficiency = {
    overall: 0.8,
    by_region: {},
    bottlenecks: [],
    opportunities: []
  };

  if (!tradeRoutes || tradeRoutes.length === 0) {
    return efficiency;
  }

  tradeRoutes.forEach(route => {
    const routeEfficiency = calculateRouteEfficiency(route, worldState);
    efficiency.by_region[route.id] = routeEfficiency;

    if (routeEfficiency < 0.6) {
      efficiency.bottlenecks.push({
        route_id: route.id,
        efficiency: routeEfficiency,
        issues: identifyRouteIssues(route, worldState)
      });
    }

    if (routeEfficiency > 0.9) {
      efficiency.opportunities.push({
        route_id: route.id,
        efficiency: routeEfficiency,
        potential: 'expansion_possible'
      });
    }
  });

  efficiency.overall = Object.values(efficiency.by_region)
    .reduce((sum, eff) => sum + eff, 0) / Object.keys(efficiency.by_region).length;

  return efficiency;
}

function calculateRouteEfficiency(route, worldState) {
  let efficiency = 1.0;

  // Factor in route conditions
  if (route.conditions) {
    if (route.conditions.weather === 'poor') efficiency -= 0.2;
    if (route.conditions.weather === 'dangerous') efficiency -= 0.4;
    if (route.conditions.security === 'low') efficiency -= 0.3;
    if (route.conditions.security === 'dangerous') efficiency -= 0.5;
  }

  // Factor in regional stability
  if (worldState.factions) {
    const routeRegions = route.regions || [];
    routeRegions.forEach(region => {
      const regionFactions = worldState.factions.filter(f => 
        f.territories && f.territories.includes(region)
      );

      regionFactions.forEach(faction => {
        if (faction.stability === 'low') efficiency -= 0.1;
        if (faction.stability === 'unstable') efficiency -= 0.2;
      });
    });
  }

  return Math.max(0.1, Math.min(1.0, efficiency));
}

function identifyRouteIssues(route, worldState) {
  const issues = [];

  if (route.conditions?.weather === 'dangerous') {
    issues.push('dangerous_weather');
  }

  if (route.conditions?.security === 'dangerous') {
    issues.push('security_concerns');
  }

  if (route.distance > 1000) {
    issues.push('excessive_distance');
  }

  return issues;
}

function identifyExternalFactors(worldState, economy) {
  const factors = [];

  // Recent events affecting economy
  if (worldState.recentEvents) {
    worldState.recentEvents.forEach(event => {
      if (event.type === 'conflict' || event.type === 'natural_disaster') {
        factors.push({
          type: 'disruption',
          source: event.type,
          impact: 'negative',
          duration: 'short_term'
        });
      }

      if (event.type === 'festival' || event.type === 'celebration') {
        factors.push({
          type: 'stimulus',
          source: event.type,
          impact: 'positive',
          duration: 'short_term'
        });
      }
    });
  }

  // Faction activities
  if (worldState.factions) {
    worldState.factions.forEach(faction => {
      if (faction.recent_actions) {
        faction.recent_actions.forEach(action => {
          if (action.type === 'military_campaign') {
            factors.push({
              type: 'war_economy',
              source: faction.name,
              impact: 'mixed',
              duration: 'medium_term'
            });
          }

          if (action.type === 'trade_agreement') {
            factors.push({
              type: 'trade_stimulus',
              source: faction.name,
              impact: 'positive',
              duration: 'long_term'
            });
          }
        });
      }
    });
  }

  return factors;
}

function identifyOpportunities(analysis, worldState) {
  const opportunities = [];

  // Supply-demand imbalances create opportunities
  Object.entries(analysis.supply_demand_imbalance).forEach(([category, imbalance]) => {
    if (imbalance > 0.3) {
      if (analysis.market_pressure[category] > 0.2) {
        opportunities.push({
          type: 'supply_shortage',
          category,
          severity: imbalance,
          recommendation: 'increase_supply',
          potential_profit: imbalance * 100
        });
      } else {
        opportunities.push({
          type: 'excess_supply',
          category,
          severity: imbalance,
          recommendation: 'create_demand',
          potential_discount: imbalance * 50
        });
      }
    }
  });

  // Trade route inefficiencies create opportunities
  if (analysis.trade_route_efficiency.overall < 0.7) {
    opportunities.push({
      type: 'trade_route_improvement',
      severity: 1 - analysis.trade_route_efficiency.overall,
      recommendation: 'invest_infrastructure',
      potential_return: (1 - analysis.trade_route_efficiency.overall) * 80
    });
  }

  return opportunities;
}

function determineOverallCondition(analysis) {
  const pressures = Object.values(analysis.market_pressure);
  const avgPressure = pressures.reduce((a, b) => a + b, 0) / pressures.length;

  const volatilities = Object.values(analysis.volatility_indicators);
  const avgVolatility = volatilities.reduce((a, b) => a + b, 0) / volatilities.length;

  if (avgVolatility > 0.4) return 'highly_volatile';
  if (avgVolatility > 0.2) return 'volatile';

  if (Math.abs(avgPressure) > 0.3) {
    return avgPressure > 0 ? 'inflationary' : 'deflationary';
  }

  if (avgPressure > 0.1) return 'expanding';
  if (avgPressure < -0.1) return 'contracting';

  return 'stable';
}

function calculateSimulationPriority(marketAnalysis, timeFactors) {
  let priority = 5;

  // High volatility increases priority
  const avgVolatility = Object.values(marketAnalysis.volatility_indicators)
    .reduce((a, b) => a + b, 0) / Object.keys(marketAnalysis.volatility_indicators).length;
  priority += avgVolatility * 3;

  // Market pressure increases priority
  const avgPressure = Object.values(marketAnalysis.market_pressure)
    .reduce((a, b) => a + Math.abs(b), 0) / Object.keys(marketAnalysis.market_pressure).length;
  priority += avgPressure * 2;

  // External factors increase priority
  priority += marketAnalysis.external_factors.length * 0.5;

  // Opportunities increase priority
  priority += marketAnalysis.opportunity_factors.length * 0.3;

  // Time factors
  priority += (timeFactors.time_multiplier - 1) * 2;

  return Math.min(priority, 10);
}

return [{
  json: {
    ...simulationConfig,
    campaigns: processedCampaigns,
    total_campaigns: processedCampaigns.length,
    simulation_timestamp: new Date().toISOString()
  }
}];

// Generate economic simulation events for current campaign
const simulationConfig = $input.first().json;
const campaign = $input.first().json.campaigns[$input.first().json.currentCampaignIndex || 0];

const { campaignId, currentEconomy, timeFactors, marketAnalysis } = campaign;

const simulationEvents = [];
const marketUpdates = {};

// Generate price adjustments based on market analysis
Object.entries(currentEconomy.markets).forEach(([category, goods]) => {
  const categoryAnalysis = marketAnalysis.market_pressure[category];

  Object.entries(goods).forEach(([goodName, goodData]) => {
    const priceEvent = generatePriceAdjustment(
      category,
      goodName,
      goodData,
      categoryAnalysis,
      timeFactors,
      marketAnalysis
    );

    if (priceEvent) {
      simulationEvents.push(priceEvent);

      // Update market data
      if (!marketUpdates[category]) {
        marketUpdates[category] = {};
      }
      marketUpdates[category][goodName] = priceEvent.new_price_data;
    }
  });
});

// Generate trade route events
if (currentEconomy.trade_routes && currentEconomy.trade_routes.length > 0) {
  currentEconomy.trade_routes.forEach(route => {
    const routeEvent = generateTradeRouteEvent(route, marketAnalysis, timeFactors);
    if (routeEvent) {
      simulationEvents.push(routeEvent);
    }
  });
}

// Generate market opportunity events
marketAnalysis.opportunity_factors.forEach(opportunity => {
  const opportunityEvent = generateOpportunityEvent(opportunity, campaignId);
  simulationEvents.push(opportunityEvent);
});

// Generate external factor events
marketAnalysis.external_factors.forEach(factor => {
  const factorEvent = generateExternalFactorEvent(factor, campaignId, currentEconomy);
  simulationEvents.push(factorEvent);
});

// Generate random economic events
const randomEventCount = Math.floor(Math.random() * 3) + 1;
for (let i = 0; i < randomEventCount; i++) {
  const randomEvent = generateRandomEconomicEvent(campaignId, currentEconomy, marketAnalysis);
  simulationEvents.push(randomEvent);
}

function generatePriceAdjustment(category, goodName, goodData, categoryAnalysis, timeFactors, marketAnalysis) {
  const currentPrice = goodData.current_price;
  const basePrice = goodData.base_price;
  const supply = goodData.supply;
  const demand = goodData.demand;

  // Calculate price pressure
  let pricePressure = (demand - supply) / 100; // -1 to 1

  // Apply market analysis factors
  pricePressure += categoryAnalysis.pressure || 0;

  // Apply time factors
  const seasonalFactor = timeFactors.seasonal_adjustment[category] || 1.0;
  const dayCycleFactor = timeFactors.day_cycle_adjustment[category] || 1.0;
  const fatigueFactor = timeFactors.market_fatigue;

  pricePressure *= seasonalFactor * dayCycleFactor * fatigueFactor;

  // Apply volatility
  const volatility = categoryAnalysis.volatility || 0.1;
  pricePressure += (Math.random() - 0.5) * volatility;

  // Calculate price change
  const maxChange = basePrice * 0.3; // Max 30% change per cycle
  const priceChange = Math.max(-maxChange, Math.min(maxChange, pricePressure * basePrice * 0.2));
  const newPrice = Math.max(basePrice * 0.3, Math.min(basePrice * 2.0, currentPrice + priceChange));

  // Only create event if price change is significant
  if (Math.abs(priceChange) > basePrice * 0.02) {
    return {
      id: `price_${category}_${goodName}_${Date.now()}`,
      type: 'price_adjustment',
      category,
      good_name: goodName,
      old_price: currentPrice,
      new_price: newPrice,
      price_change: priceChange,
      price_change_percent: (priceChange / currentPrice) * 100,
      base_price: basePrice,
      factors: {
        supply_demand_pressure: pricePressure,
        seasonal_factor: seasonalFactor,
        day_cycle_factor: dayCycleFactor,
        volatility_factor: volatility,
        fatigue_factor: fatigueFactor
      },
      market_condition: marketAnalysis.overall_condition,
      impact_level: calculatePriceImpactLevel(Math.abs(priceChange / basePrice)),
      timestamp: new Date().toISOString()
    };
  }

  return null;
}

function generateTradeRouteEvent(route, marketAnalysis, timeFactors) {
  const efficiency = marketAnalysis.trade_route_efficiency.by_region[route.id] || 0.8;

  // Generate route condition changes
  let conditionChange = 0;

  // Random deterioration
  if (Math.random() < 0.2) {
    conditionChange -= Math.random() * 0.2;
  }

  // Random improvement
  if (Math.random() < 0.1) {
    conditionChange += Math.random() * 0.15;
  }

  // Apply time factors
  conditionChange *= timeFactors.time_multiplier * 0.5;

  const newEfficiency = Math.max(0.1, Math.min(1.0, efficiency + conditionChange));

  if (Math.abs(conditionChange) > 0.05) {
    return {
      id: `route_${route.id}_${Date.now()}`,
      type: 'trade_route_change',
      route_id: route.id,
      route_name: route.name || `Route ${route.id}`,
      old_efficiency: efficiency,
      new_efficiency: newEfficiency,
      efficiency_change: conditionChange,
      affected_regions: route.regions || [],
      affected_goods: route.goods || [],
      cause: determineRouteCause(conditionChange),
      impact_level: calculateRouteImpactLevel(Math.abs(conditionChange)),
      timestamp: new Date().toISOString()
    };
  }

  return null;
}

function generateOpportunityEvent(opportunity, campaignId) {
  return {
    id: `opportunity_${opportunity.type}_${Date.now()}`,
    type: 'economic_opportunity',
    opportunity_type: opportunity.type,
    category: opportunity.category,
    severity: opportunity.severity,
    recommendation: opportunity.recommendation,
    potential_value: opportunity.potential_profit || opportunity.potential_discount || 0,
    campaign_id: campaignId,
    description: generateOpportunityDescription(opportunity),
    requirements: generateOpportunityRequirements(opportunity),
    time_sensitivity: calculateOpportunityTimeSensitivity(opportunity),
    player_actionable: true,
    timestamp: new Date().toISOString()
  };
}

function generateExternalFactorEvent(factor, campaignId, currentEconomy) {
  return {
    id: `external_${factor.type}_${Date.now()}`,
    type: 'external_economic_factor',
    factor_type: factor.type,
    source: factor.source,
    impact: factor.impact,
    duration: factor.duration,
    campaign_id: campaignId,
    affected_markets: determineAffectedMarkets(factor, currentEconomy),
    magnitude: calculateFactorMagnitude(factor),
    description: generateFactorDescription(factor),
    player_visible: factor.duration === 'short_term' || Math.random() < 0.3,
    timestamp: new Date().toISOString()
  };
}

function generateRandomEconomicEvent(campaignId, currentEconomy, marketAnalysis) {
  const eventTypes = [
    'merchant_arrival',
    'resource_discovery',
    'guild_activity',
    'market_rumor',
    'trade_embargo',
    'economic_boom',
    'recession',
    'innovation'
  ];

  const eventType = eventTypes[Math.floor(Math.random() * eventTypes.length)];
  const severity = Math.random();

  return {
    id: `random_${eventType}_${Date.now()}`,
    type: 'random_economic_event',
    event_type: eventType,
    severity,
    campaign_id: campaignId,
    affected_regions: ['all'],
    affected_markets: determineRandomEventMarkets(eventType, currentEconomy),
    description: generateRandomEventDescription(eventType, severity),
    immediate_effects: generateRandomEventEffects(eventType, severity),
    player_hooks: generateRandomEventHooks(eventType, severity),
    timestamp: new Date().toISOString()
  };
}

// Helper functions for event generation
function calculatePriceImpactLevel(changePercent) {
  if (changePercent < 0.05) return 'minor';
  if (changePercent < 0.15) return 'moderate';
  if (changePercent < 0.25) return 'significant';
  return 'major';
}

function determineRouteCause(change) {
  if (change > 0) {
    const causes = ['improved_security', 'better_weather', 'infrastructure_investment', 'reduced_banditry'];
    return causes[Math.floor(Math.random() * causes.length)];
  } else {
    const causes = ['increased_banditry', 'poor_weather', 'road_damage', 'military_activity', 'monster_attacks'];
    return causes[Math.floor(Math.random() * causes.length)];
  }
}

function calculateRouteImpactLevel(change) {
  if (Math.abs(change) < 0.05) return 'minor';
  if (Math.abs(change) < 0.15) return 'moderate';
  if (Math.abs(change) < 0.25) return 'significant';
  return 'major';
}

function generateOpportunityDescription(opportunity) {
  const descriptions = {
    'supply_shortage': `High demand for ${opportunity.category} goods creates profitable opportunities`,
    'excess_supply': `Surplus of ${opportunity.category} goods available at discounted prices`,
    'trade_route_improvement': `Investment in trade infrastructure could yield significant returns`
  };
  return descriptions[opportunity.type] || 'Economic opportunity detected';
}

function generateOpportunityRequirements(opportunity) {
  const requirements = {
    'supply_shortage': ['capital_investment', 'supply_chain_access', 'distribution_network'],
    'excess_supply': ['storage_facilities', 'marketing', 'transportation'],
    'trade_route_improvement': ['infrastructure_investment', 'security_arrangements', 'political_support']
  };
  return requirements[opportunity.type] || ['resources', 'planning'];
}

function calculateOpportunityTimeSensitivity(opportunity) {
  if (opportunity.type === 'supply_shortage') return 'high';
  if (opportunity.type === 'excess_supply') return 'medium';
  return 'low';
}

function determineAffectedMarkets(factor, currentEconomy) {
  const marketMappings = {
    'disruption': ['commodities', 'services'],
    'stimulus': ['services', 'magical'],
    'war_economy': ['weapons', 'armor', 'services'],
    'trade_stimulus': ['commodities', 'services', 'magical']
  };

  return marketMappings[factor.type] || Object.keys(currentEconomy.markets);
}

function calculateFactorMagnitude(factor) {
  const magnitudes = {
    'short_term': 0.3,
    'medium_term': 0.5,
    'long_term': 0.7
  };

  return magnitudes[factor.duration] || 0.5;
}

function generateFactorDescription(factor) {
  const descriptions = {
    'disruption': `${factor.source} is disrupting normal economic activity`,
    'stimulus': `${factor.source} is stimulating economic growth`,
    'war_economy': `${factor.source} is creating war economy conditions`,
    'trade_stimulus': `${factor.source} is boosting trade activity`
  };

  return descriptions[factor.type] || 'External economic factor affecting markets';
}

function determineRandomEventMarkets(eventType, currentEconomy) {
