// Process economic narratives and prepare world state updates
const eventData = $input.first().json;
const deepseekResponse = $input.last().json;

let narrativeData = {};
try {
  const content = deepseekResponse.choices[0].message.content;
  narrativeData = JSON.parse(content);
} catch (error) {
  console.error('Failed to parse DeepSeek economic narrative:', error);
  narrativeData = {
    narrative_description: 'Economic conditions continue to evolve.',
    player_perception: 'Players may notice changes in prices and availability.',
    adventure_hooks: 'New opportunities may arise from economic changes.',
    social_impact: 'Various social classes may be affected differently.',
    future_consequences: 'Further economic developments may follow.'
  };
}

// Enrich economic events with narratives
const enrichedEvents = eventData.simulationEvents.map((event, index) => {
  const eventNarrative = narrativeData.events?.[index] || narrativeData;

  return {
    ...event,
    narrative_description: eventNarrative.narrative_description || `Economic ${event.type} affects the world`,
    player_perception: eventNarrative.player_perception || 'This change may be noticed through market observation.',
    adventure_hooks: eventNarrative.adventure_hooks || 'Economic opportunities may exist.',
    social_impact: eventNarrative.social_impact || 'Various groups may be affected.',
    future_consequences: eventNarrative.future_consequences || 'Further effects may develop.',
    processed: true
  };
});

// Apply market updates to economy
const updatedEconomy = applyMarketUpdates(eventData.currentEconomy, eventData.marketUpdates);

// Calculate economic summary statistics
const economicSummary = calculateEconomicSummary(enrichedEvents, updatedEconomy, eventData.marketAnalysis);

function applyMarketUpdates(currentEconomy, marketUpdates) {
  const updated = JSON.parse(JSON.stringify(currentEconomy)); // Deep clone

  // Apply price updates
  Object.entries(marketUpdates).forEach(([category, goods]) => {
    if (updated.markets[category]) {
      Object.entries(goods).forEach(([goodName, newData]) => {
        if (updated.markets[category][goodName]) {
          updated.markets[category][goodName] = {
            ...updated.markets[category][goodName],
            ...newData
          };
        }
      });
    }
  });

  // Update price history
  const priceSnapshot = generatePriceSnapshot(updated.markets);
  updated.price_history = [...(updated.price_history || []), priceSnapshot].slice(-20); // Keep last 20 snapshots

  // Update market conditions
  updated.market_conditions = calculateMarketConditions(updated);

  updated.last_updated = new Date().toISOString();

  return updated;
}

function generatePriceSnapshot(markets) {
  const snapshot = {};

  Object.entries(markets).forEach(([category, goods]) => {
    snapshot[category] = {};
    Object.entries(goods).forEach(([goodName, goodData]) => {
      snapshot[category][goodName] = goodData.current_price;
    });
  });

  return {
    prices: snapshot,
    timestamp: new Date().toISOString()
  };
}

function calculateMarketConditions(economy) {
  const allPrices = [];
  const allPriceChanges = [];

  Object.values(economy.markets).forEach(goods => {
    Object.values(goods).forEach(goodData => {
      allPrices.push(goodData.current_price);
      const priceChange = (goodData.current_price - goodData.base_price) / goodData.base_price;
      allPriceChanges.push(priceChange);
    });
  });

  const avgPriceChange = allPriceChanges.reduce((a, b) => a + b, 0) / allPriceChanges.length;
  const volatility = Math.sqrt(
    allPriceChanges.reduce((sum, change) => sum + Math.pow(change - avgPriceChange, 2), 0) / allPriceChanges.length
  );

  if (avgPriceChange > 0.1) return 'inflationary';
  if (avgPriceChange < -0.1) return 'deflationary';
  if (volatility > 0.2) return 'volatile';
  if (volatility < 0.05) return 'stable';

  return 'normal';
}

function calculateEconomicSummary(events, updatedEconomy, marketAnalysis) {
  const priceEvents = events.filter(e => e.type === 'price_adjustment');
  const opportunityEvents = events.filter(e => e.type === 'economic_opportunity');
  const externalEvents = events.filter(e => e.type === 'external_economic_factor');

  return {
    total_events: events.length,
    price_changes: {
      increases: priceEvents.filter(e => e.price_change > 0).length,
      decreases: priceEvents.filter(e => e.price_change < 0).length,
      significant_changes: priceEvents.filter(e => Math.abs(e.price_change_percent) > 10).length
    },
    opportunities: {
      total: opportunityEvents.length,
      high_value: opportunityEvents.filter(e => e.potential_value > 100).length,
      time_sensitive: opportunityEvents.filter(e => e.time_sensitivity === 'high').length
    },
    external_factors: {
      total: externalEvents.length,
      positive_impact: externalEvents.filter(e => e.impact === 'positive').length,
      negative_impact: externalEvents.filter(e => e.impact === 'negative').length
    },
    market_conditions: updatedEconomy.market_conditions,
    overall_volatility: marketAnalysis.overall_condition === 'volatile' || marketAnalysis.overall_condition === 'highly_volatile',
    player_actionable_events: events.filter(e => e.player_actionable || e.adventure_hooks).length
  };
}

return [{
  json: {
    campaignId: eventData.campaignId,
    original_events: eventData.simulationEvents,
    enriched_events: enrichedEvents,
    updated_economy: updatedEconomy,
    economic_summary: economicSummary,
    market_updates: eventData.marketUpdates,
    market_analysis: eventData.marketAnalysis,
    time_factors: eventData.timeFactors,
    narrative_summary: narrativeData.narrative_description || 'Economic simulation cycle completed',
    timestamp: new Date().toISOString(),
    processed_by: 'economic-simulator'
  }
}];

// Generate economic simulation summary
const economicData = $input.first().json;

const summary = {
  simulation_id: `econ_${economicData.campaignId}_${Date.now()}`,
  campaign_id: economicData.campaignId,
  processing_time: new Date().toISOString(),
  economic_overview: {
    market_condition: economicData.updated_economy.market_conditions,
    total_events: economicData.economic_summary.total_events,
    price_volatility: economicData.market_analysis.overall_condition,
    player_opportunities: economicData.economic_summary.player_actionable_events
  },
  price_analysis: {
    price_increases: economicData.economic_summary.price_changes.increases,
    price_decreases: economicData.economic_summary.price_changes.decreases,
    significant_movements: economicData.economic_summary.price_changes.significant_changes,
    most_affected_categories: analyzeMostAffectedCategories(economicData.enriched_events),
    price_trends: calculatePriceTrends(economicData.updated_economy)
  },
  opportunity_analysis: {
    total_opportunities: economicData.economic_summary.opportunities.total,
    high_value_opportunities: economicData.economic_summary.opportunities.high_value,
    urgent_opportunities: economicData.economic_summary.opportunities.time_sensitive,
    opportunity_types: categorizeOpportunities(economicData.enriched_events),
    market_gaps: identifyMarketGaps(economicData.updated_economy)
  },
  external_factors: {
    total_factors: economicData.economic_summary.external_factors.total,
    positive_factors: economicData.economic_summary.external_factors.positive_impact,
    negative_factors: economicData.economic_summary.external_factors.negative_impact,
    factor_impact_duration: analyzeFactorDurations(economicData.enriched_events)
  },
  narrative_summary: economicData.narrative_summary,
  player_relevance: {
    immediate_hooks: extractPlayerHooks(economicData.enriched_events),
    medium_term_opportunities: identifyMediumTermOpportunities(economicData.enriched_events),
    long_term_implications: analyzeLongTermImplications(economicData.updated_economy),
    investment_opportunities: identifyInvestmentOpportunities(economicData.enriched_events)
  },
  next_simulation_factors: {
    volatility_carryover: calculateVolatilityCarryover(economicData.market_analysis),
    momentum_factors: calculateMomentumFactors(economicData.economic_summary),
    recommended_focus: determineRecommendedFocus(economicData.economic_summary, economicData.market_analysis)
  }
};

function analyzeMostAffectedCategories(events) {
  const categoryCounts = {};

  events.forEach(event => {
    if (event.category) {
      categoryCounts[event.category] = (categoryCounts[event.category] || 0) + 1;
    }
  });

  return Object.entries(categoryCounts)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 3)
    .map(([category, count]) => ({ category, impact_count: count }));
}

function calculatePriceTrends(economy) {
  const trends = {};

  Object.entries(economy.markets).forEach(([category, goods]) => {
    let increases = 0;
    let decreases = 0;

    Object.values(goods).forEach(good => {
      if (good.current_price > good.base_price) increases++;
      if (good.current_price < good.base_price) decreases++;
    });

    const total = increases + decreases;
    if (total > 0) {
      trends[category] = {
        trend: increases > decreases ? 'rising' : decreases > increases ? 'falling' : 'stable',
        momentum: Math.abs(increases - decreases) / total,
        price_level: calculateAveragePriceLevel(goods)
      };
    }
  });

  return trends;
}

function calculateAveragePriceLevel(goods) {
  const prices = Object.values(goods).map(g => g.current_price / g.base_price);
  const avgPriceLevel = prices.reduce((a, b) => a + b, 0) / prices.length;

  if (avgPriceLevel > 1.2) return 'high';
  if (avgPriceLevel < 0.8) return 'low';
  return 'normal';
}

function categorizeOpportunities(events) {
  const types = {};

  events.filter(e => e.type === 'economic_opportunity').forEach(event => {
    types[event.opportunity_type] = (types[event.opportunity_type] || 0) + 1;
  });

  return types;
}

function identifyMarketGaps(economy) {
  const gaps = [];

  Object.entries(economy.markets).forEach(([category, goods]) => {
    Object.entries(goods).forEach(([goodName, goodData]) => {
      const priceRatio = goodData.current_price / goodData.base_price;
      const supplyDemandRatio = goodData.supply / goodData.demand;

      if (supplyDemandRatio > 1.5 && priceRatio > 1.2) {
        gaps.push({
          category,
          good: goodName,
          gap_type: 'overpriced_oversupply',
          severity: priceRatio * supplyDemandRatio
        });
      } else if (supplyDemandRatio < 0.7 && priceRatio < 0.8) {
        gaps.push({
          category,
          good: goodName,
          gap_type: 'undersupplied_undervalued',
          severity: (2 - priceRatio) * (2 - supplyDemandRatio)
        });
      }
    });
  });

  return gaps.sort((a, b) => b.severity - a.severity).slice(0, 5);
}

function analyzeFactorDurations(events) {
  const durations = {};

  events.filter(e => e.type === 'external_economic_factor').forEach(event => {
    durations[event.duration] = (durations[event.duration] || 0) + 1;
  });

  return durations;
}

function extractPlayerHooks(events) {
  return events
    .filter(event => event.adventure_hooks && event.adventure_hooks.length > 0)
    .map(event => ({
      event_id: event.id,
      event_type: event.type,
      hooks: event.adventure_hooks,
      urgency: event.time_sensitivity || 'medium',
      potential_reward: event.potential_value || 0
    }));
}

function identifyMediumTermOpportunities(events) {
  return events
    .filter(event => event.type === 'economic_opportunity' && event.time_sensitivity === 'medium')
    .map(event => ({
      opportunity_type: event.opportunity_type,
      category: event.category,
      potential_value: event.potential_value,
      requirements: event.requirements
    }));
}

function analyzeLongTermImplications(economy) {
  const implications = [];

  // Price level analysis
  const avgPriceLevel = calculateOverallPriceLevel(economy);
  if (avgPriceLevel > 1.2) {
    implications.push({
      type: 'inflationary_pressure',
      description: 'Sustained high prices may lead to economic slowdown',
      timeline: '3-6 months',
      severity: 'moderate'
    });
  }

  // Supply chain analysis
  const supplyIssues = identifySupplyChainIssues(economy);
  if (supplyIssues.length > 0) {
    implications.push({
      type: 'supply_chain_vulnerability',
      description: 'Supply chain disruptions may create long-term shortages',
      timeline: '2-4 months',
      severity: 'high'
    });
  }

  return implications;
}

function calculateOverallPriceLevel(economy) {
  const allPriceRatios = [];

  Object.values(economy.markets).forEach(goods => {
    Object.values(goods).forEach(good => {
      allPriceRatios.push(good.current_price / good.base_price);
    });
  });

  return allPriceRatios.reduce((a, b) => a + b, 0) / allPriceRatios.length;
}

function identifySupplyChainIssues(economy) {
  const issues = [];

  Object.entries(economy.markets).forEach(([category, goods]) => {
    Object.entries(goods).forEach(([goodName, goodData]) => {
      if (goodData.supply < goodData.demand * 0.7) {
        issues.push({ category, good: goodName, severity: (goodData.demand - goodData.supply) / goodData.demand });
      }
    });
  });

  return issues;
}

function identifyInvestmentOpportunities(events) {
  return events
    .filter(event => event.type === 'economic_opportunity' && event.potential_value > 50)
    .map(event => ({
      opportunity_type: event.opportunity_type,
      category: event.category,
      investment_required: estimateInvestmentRequired(event),
      expected_return: event.potential_value,
      time_horizon: event.time_sensitivity === 'high' ? 'short' : 'medium',
      risk_level: calculateRiskLevel(event)
    }));
}

function estimateInvestmentRequired(event) {
  const baseRequirements = {
    'supply_shortage': 100,
    'excess_supply': 50,
    'trade_route_improvement': 200
  };

  return baseRequirements[event.opportunity_type] || 75;
}

function calculateRiskLevel(event) {
  if (event.severity > 0.7) return 'high';
  if (event.severity > 0.4) return 'medium';
  return 'low';
}

function calculateVolatilityCarryover(marketAnalysis) {
  const volatilityMap = {
    'stable': 0.8,
    'normal': 1.0,
    'volatile': 1.3,
    'highly_volatile': 1.6,
    'inflationary': 1.2,
    'deflationary': 1.1
  };

  return volatilityMap[marketAnalysis.overall_condition] || 1.0;
}

function calculateMomentumFactors(economicSummary) {
  const priceChangeBalance = economicSummary.price_changes.increases - economicSummary.price_changes.decreases;
  const opportunityRatio = economicSummary.opportunities.total / Math.max(economicSummary.total_events, 1);

  return {
    price_momentum: Math.max(-1, Math.min(1, priceChangeBalance / 10)),
    opportunity_momentum: Math.min(1, opportunityRatio * 2),
    economic_health: economicSummary.external_factors.positive_impact > economicSummary.external_factors.negative_impact ? 'positive' : 'negative'
  };
}

function determineRecommendedFocus(economicSummary, marketAnalysis) {
  if (economicSummary.player_actionable_events > 3) {
    return 'player_opportunities';
  }

  if (marketAnalysis.overall_condition === 'volatile' || marketAnalysis.overall_condition === 'highly_volatile') {
    return 'market_stabilization';
  }

  if (economicSummary.opportunities.total > 2) {
    return 'opportunity_exploitation';
  }

  return 'routine_monitoring';
}

return [{ json: summary }];
